INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6662526, 996058, 51747, '<td valign="top">Oh, that had to hurt!!</td>', 'Oh, that had to hurt!!', '2012-02-02 21:49:27.000000', NULL, 1),
(6662529, 994120, 51747, '<td valign="top">Ahhh   The smell of wet dog!   lol  It looks like they must have had fun that day.</td>', 'Ahhh   The smell of wet dog!   lol  It looks like they must have had fun that day.', '2012-02-02 21:53:01.000000', NULL, 1),
(6662550, 994624, 46918, '<td valign="top">This is a good shot... I like the humor...even though being homeles is not funny. Great DOF, great subject.,....I like it</td>', 'This is a good shot... I like the humor...even though being homeles is not funny. Great DOF, great subject.,....I like it', '2012-02-02 22:16:08.000000', NULL, 1),
(6662570, 995821, 83313, '<td valign="top">A nice piece of old fashionedness. The obvious tilt really hurts this, I''m afraid. A bit of white balance adjustment might help too. Some minor adjustments could really give this a lot more impact. The composition is really odd as well, with subject at the far sides and a big empty space in the middle drawing my attention. Sorry to pour on the critique like that, but I hope it is helpful.</td>', 'A nice piece of old fashionedness. The obvious tilt really hurts this, I''m afraid. A bit of white balance adjustment might help too. Some minor adjustments could really give this a lot more impact. The composition is really odd as well, with subject at the far sides and a big empty space in the middle drawing my attention. Sorry to pour on the critique like that, but I hope it is helpful.', '2012-02-02 22:39:56.000000', NULL, 1),
(6662571, 993696, 83313, '<td valign="top">Like a vague memory from my childhood.</td>', 'Like a vague memory from my childhood.', '2012-02-02 22:41:00.000000', NULL, 1),
(6662572, 996483, 83313, '<td valign="top">Looks like an old postcard. Nice work.</td>', 'Looks like an old postcard. Nice work.', '2012-02-02 22:42:10.000000', NULL, 1),
(6662574, 996422, 83313, '<td valign="top">How could I not love a shot like this? Great catch of the action.</td>', 'How could I not love a shot like this? Great catch of the action.', '2012-02-02 22:43:31.000000', NULL, 1),
(6662576, 996380, 83313, '<td valign="top">The stereotypical "girl next door". Very pretty, lovely eyes, and well photographed.</td>', 'The stereotypical "girl next door". Very pretty, lovely eyes, and well photographed.', '2012-02-02 22:44:32.000000', NULL, 1),
(6662578, 995996, 25787, '<td valign="top">I''ve been trying to shoot eagles myself, and I know how hard it is to get them in flight. The pose, lighting and angle are great. Shot is probably not as sharp as you would have liked and is over sharpened to compensate. I hope to get one like this someday.</td>', 'I''ve been trying to shoot eagles myself, and I know how hard it is to get them in flight. The pose, lighting and angle are great. Shot is probably not as sharp as you would have liked and is over sharpened to compensate. I hope to get one like this someday.', '2012-02-02 22:46:59.000000', NULL, 1),
(6662579, 996417, 83313, '<td valign="top">Grog lost in desert at night. Grog should have listened to female and asked directions.</td>', 'Grog lost in desert at night. Grog should have listened to female and asked directions.', '2012-02-02 22:47:32.000000', NULL, 1),
