(6664250, 994624, 32011, '<td valign="top">Wonderful obsure scene... done well to capture it, done spectacularly to make it as great as this.</td>', 'Wonderful obsure scene... done well to capture it, done spectacularly to make it as great as this.', '2012-02-05 04:43:32.000000', NULL, 1),
(6664252, 996174, 32011, '<td valign="top">One of my favourite images in this months free-study.  Love the processing and the composition... the crop... WONDERFUL.  I''d happily have this hanging on a wall in my home.</td>', 'One of my favourite images in this months free-study.  Love the processing and the composition... the crop... WONDERFUL.  I''d happily have this hanging on a wall in my home.', '2012-02-05 04:46:24.000000', NULL, 1),
(6664253, 995405, 32011, '<td valign="top">Magical and mystical.  Beautiful image... the processing and composition is perfect.</td>', 'Magical and mystical.  Beautiful image... the processing and composition is perfect.', '2012-02-05 04:49:19.000000', NULL, 1),
(6664254, 995522, 32011, '<td valign="top">This is my favourite image in the free study... love it so much that I''ve picked this to be the image I give my 1,000th comment to.  I love the moment you''ve captured, adore the processing and am totally in awe... bumping it from the original 9 I gave during the voting phase to a 10...</td>', 'This is my favourite image in the free study... love it so much that I''ve picked this to be the image I give my 1,000th comment to.  I love the moment you''ve captured, adore the processing and am totally in awe... bumping it from the original 9 I gave during the voting phase to a 10...', '2012-02-05 04:52:33.000000', NULL, 1),
(6664265, 994895, 56502, '<td valign="top">Well, we all seem to have to get used to this automatic filling in of titles.</td>', 'Well, we all seem to have to get used to this automatic filling in of titles.', '2012-02-05 05:42:57.000000', NULL, 1),
