(6664282, 995164, 91496, '<td valign="top">Nice tones here.  Perhps cropping off some of the sky at the top would be a more powerful composition.</td>', 'Nice tones here.  Perhps cropping off some of the sky at the top would be a more powerful composition.', '2012-02-05 07:14:03.000000', NULL, 1),
(6664394, 996100, 118154, '<td valign="top">Lovely quality mono.</td>', 'Lovely quality mono.', '2012-02-05 11:01:09.000000', NULL, 1),
(6664396, 996228, 118154, '<td valign="top">So far it is.</td>', 'So far it is.', '2012-02-05 11:02:19.000000', NULL, 1),
(6664400, 996481, 118154, '<td valign="top">Really glad I look at these images more than once as I now see this shot in a much better light than before and like it very much.</td>', 'Really glad I look at these images more than once as I now see this shot in a much better light than before and like it very much.', '2012-02-05 11:04:34.000000', NULL, 1),
(6664401, 996163, 118154, '<td valign="top">I like this but the face looks very bored and uninterested in my view.</td>', 'I like this but the face looks very bored and uninterested in my view.', '2012-02-05 11:05:28.000000', NULL, 1),
(6664415, 995400, 94265, '<td valign="top">I''m making a point of commenting on the images I scored the highest. This is just fantastic; vibrant colours, crisp focus, nice bokeh and an appealing subject. I love parrots. Great job and good luck!</td>', 'I''m making a point of commenting on the images I scored the highest. This is just fantastic; vibrant colours, crisp focus, nice bokeh and an appealing subject. I love parrots. Great job and good luck!', '2012-02-05 11:14:30.000000', NULL, 1),
(6664416, 994101, 94265, '<td valign="top">I''m making a point of commenting on the images I scored the highest. This is just gorgeous, the lighting couldn''t be more perfect. Lovely and crisp on the focus, a beautiful subject, well done.</td>', 'I''m making a point of commenting on the images I scored the highest. This is just gorgeous, the lighting couldn''t be more perfect. Lovely and crisp on the focus, a beautiful subject, well done.', '2012-02-05 11:15:31.000000', NULL, 1),
(6664418, 994779, 94265, '<td valign="top">I''m making a point of commenting on the images I scored the highest. The focus and clarity of this is outstanding. Great vibrant colours, good composition, crisp details, fabulous! Well done.</td>', 'I''m making a point of commenting on the images I scored the highest. The focus and clarity of this is outstanding. Great vibrant colours, good composition, crisp details, fabulous! Well done.', '2012-02-05 11:16:18.000000', NULL, 1),
(6664419, 996515, 94265, '<td valign="top">I''m making a point of commenting on the images I scored the highest. I''m not 100% sure what it is about this one I love so much but it''s just awesome; nice b&amp;w conversion, good sharpness, a slightly unusual subject (we don''t really get that many sheep shots on dpc!) and a fantastic title. The sheep looks like she''s smiling. Oh look, I guess I do know what I love about this, lol. Good luck!</td>', 'I''m making a point of commenting on the images I scored the highest. I''m not 100% sure what it is about this one I love so much but it''s just awesome; nice b&w conversion, good sharpness, a slightly unusual subject (we don''t really get that many sheep shots on dpc!) and a fantastic title. The sheep looks like she''s smiling. Oh look, I guess I do know what I love about this, lol. Good luck!', '2012-02-05 11:19:07.000000', NULL, 1),
(6664420, 996522, 94265, '<td valign="top">Beautifully simple, love those evening sky colours, nice clear capture of the geese in flight. This would make a great wall canvas. Lovely shot, good luck with it.</td>', 'Beautifully simple, love those evening sky colours, nice clear capture of the geese in flight. This would make a great wall canvas. Lovely shot, good luck with it.', '2012-02-05 11:20:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6664421, 991343, 94265, '<td valign="top">That sky is phenomenal, wonderful capture, a really goregeous scenery/sky shot.</td>', 'That sky is phenomenal, wonderful capture, a really goregeous scenery/sky shot.', '2012-02-05 11:20:43.000000', NULL, 1),
(6664422, 996519, 113016, '<td valign="top">Fun concept</td>', 'Fun concept', '2012-02-05 11:20:54.000000', NULL, 1),
(6664425, 996348, 94265, '<td valign="top">Absolutely stunning. Lovely and crisp, beautiful animal, nice composition. Shame there''s no catchlight in the left eye but this is a great shot.</td>', 'Absolutely stunning. Lovely and crisp, beautiful animal, nice composition. Shame there''s no catchlight in the left eye but this is a great shot.', '2012-02-05 11:21:53.000000', NULL, 1),
(6664426, 995953, 94265, '<td valign="top">Great DOF, love your subject. I might have selected the wee spot where the light speckles on the (is that a potato?) and lowered the cyan and magenta channels as they''re a bit prominent. Otherwise, I really like this, good luck with it.</td>', 'Great DOF, love your subject. I might have selected the wee spot where the light speckles on the (is that a potato?) and lowered the cyan and magenta channels as they''re a bit prominent. Otherwise, I really like this, good luck with it.', '2012-02-05 11:24:08.000000', NULL, 1),
(6664427, 996256, 113016, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2012-02-05 11:24:47.000000', NULL, 1),
(6664428, 995785, 94265, '<td valign="top">A great moody shot, love the cloudy sky and splashing water on the boat, very atmospheric. I like the title but really wish that fellow in the background wasn''t there, he doesn''t particularly distract in the shot but his presence makes the title feel moot for me, if that makes sense. Still, love the image, gave you an 8 and hope it does well.</td>', 'A great moody shot, love the cloudy sky and splashing water on the boat, very atmospheric. I like the title but really wish that fellow in the background wasn''t there, he doesn''t particularly distract in the shot but his presence makes the title feel moot for me, if that makes sense. Still, love the image, gave you an 8 and hope it does well.', '2012-02-05 11:25:28.000000', NULL, 1),
(6664429, 995135, 52510, '<td valign="top">Awesome</td>', 'Awesome', '2012-02-05 11:26:00.000000', NULL, 1),
(6664430, 996400, 94265, '<td valign="top">Lots of character in that lovely wee face! Sort of wish he was looking at the camera but it doesn''t spoil the image that he isn''t. Nice dark contrast and clear focus on his hair. Good work.</td>', 'Lots of character in that lovely wee face! Sort of wish he was looking at the camera but it doesn''t spoil the image that he isn''t. Nice dark contrast and clear focus on his hair. Good work.', '2012-02-05 11:26:41.000000', NULL, 1),
(6664432, 995674, 94265, '<td valign="top">Lovely crisp details, I''ve always thought horses muzzles look so soft and friendly, nice to see a clear image of it. Nice colours too.</td>', 'Lovely crisp details, I''ve always thought horses muzzles look so soft and friendly, nice to see a clear image of it. Nice colours too.', '2012-02-05 11:27:50.000000', NULL, 1),
(6664437, 995135, 94265, '<td valign="top">I feel this could have been brightened a bit more without any loss of detail on the snow; I don''t know if it''s noise or just the processing but it''s a wee bit soft-looking too. That aside though, it''s a beautiful image, a great shot of such lovely animals and couldn''t have been composed better. Love the bokehd fox in the back, it looks as if he''s scowling at the photographer while the one in front looks curious. Congrats on such a pretty capture.</td>', 'I feel this could have been brightened a bit more without any loss of detail on the snow; I don''t know if it''s noise or just the processing but it''s a wee bit soft-looking too. That aside though, it''s a beautiful image, a great shot of such lovely animals and couldn''t have been composed better. Love the bokehd fox in the back, it looks as if he''s scowling at the photographer while the one in front looks curious. Congrats on such a pretty capture.', '2012-02-05 11:30:52.000000', NULL, 1),
(6664438, 995838, 94265, '<td valign="top">She looks like a rock and roll fan, haha. Gorgeous animals, what a brilliant moment to capture!</td>', 'She looks like a rock and roll fan, haha. Gorgeous animals, what a brilliant moment to capture!', '2012-02-05 11:31:42.000000', NULL, 1),
(6664440, 995498, 94265, '<td valign="top">I love the title, made me chuckle. Beautiful horse, looks so much like Black Beauty with that white spot on his head. Nice composition. Worth another look, bumping this from a 7 to an 8.</td>', 'I love the title, made me chuckle. Beautiful horse, looks so much like Black Beauty with that white spot on his head. Nice composition. Worth another look, bumping this from a 7 to an 8.', '2012-02-05 11:32:34.000000', NULL, 1),
(6664441, 996047, 94265, '<td valign="top">Haha, very nice and made me smile. Great focus on the cat''s face, you can see so much detail in the eyes and fur. Good job.</td>', 'Haha, very nice and made me smile. Great focus on the cat''s face, you can see so much detail in the eyes and fur. Good job.', '2012-02-05 11:33:12.000000', NULL, 1),
(6664445, 995917, 94265, '<td valign="top">Contrast could do with a boost but this is a great macro, fantastic details, I can see all the little wear-and-tear scratches on the metal. Good composition too, best of luck with this.</td>', 'Contrast could do with a boost but this is a great macro, fantastic details, I can see all the little wear-and-tear scratches on the metal. Good composition too, best of luck with this.', '2012-02-05 11:34:31.000000', NULL, 1),
(6664447, 996246, 76335, '<td valign="top">Nicely composed. Love the concentrated gaze over the glasses. And, of course, the beard.</td>', 'Nicely composed. Love the concentrated gaze over the glasses. And, of course, the beard.', '2012-02-05 11:35:57.000000', NULL, 1),
(6664448, 995849, 76335, '<td valign="top">Absolutely love the composition. And it works in black and white. The processing is heavyhanded.</td>', 'Absolutely love the composition. And it works in black and white. The processing is heavyhanded.', '2012-02-05 11:36:48.000000', NULL, 1),
(6664449, 995468, 76335, '<td valign="top">Nicely extracted.</td>', 'Nicely extracted.', '2012-02-05 11:37:47.000000', NULL, 1),
(6664450, 996529, 76335, '<td valign="top">Foreboding.</td>', 'Foreboding.', '2012-02-05 11:38:03.000000', NULL, 1),
