(6665684, 996210, 114225, '<td valign="top">Beautiful. I can feel the coolness of the evening as the waves crash by my feet.</td>', 'Beautiful. I can feel the coolness of the evening as the waves crash by my feet.', '2012-02-06 21:58:39.000000', NULL, 1),
(6665685, 996179, 114225, '<td valign="top">What a cool building, and great composition. But that heavy vignette is so unnatural and is reducing the overall image for me.</td>', 'What a cool building, and great composition. But that heavy vignette is so unnatural and is reducing the overall image for me.', '2012-02-06 21:59:38.000000', NULL, 1),
(6665687, 996514, 114225, '<td valign="top">The curves of the tentacles really make this shot.</td>', 'The curves of the tentacles really make this shot.', '2012-02-06 22:00:11.000000', NULL, 1),
(6665688, 994880, 114225, '<td valign="top">Very cool. Drawing the viewers eyes in and then letting them explore is a great choice.</td>', 'Very cool. Drawing the viewers eyes in and then letting them explore is a great choice.', '2012-02-06 22:01:36.000000', NULL, 1),
(6665689, 995398, 49018, '<td valign="top">Mariuca, perhaps?<br/>In any case, excellent use of wideangle distortion and of the resulting circularity, high key BW really effective.<br/>Really luminous. The angle of the boy mirrors but not quite, creating an accent.<br/>The gaze is really free to travel and still well conducted from the boy in a circle and back, to the lady, and again. Like a metal ball in one of those conic vases, with a hole in the bottom.<br/>A 9 before I fall through.</td>', 'Mariuca, perhaps?In any case, excellent use of wideangle distortion and of the resulting circularity, high key BW really effective.Really luminous. The angle of the boy mirrors but not quite, creating an accent.The gaze is really free to travel and still well conducted from the boy in a circle and back, to the lady, and again. Like a metal ball in one of those conic vases, with a hole in the bottom.A 9 before I fall through.', '2012-02-06 22:02:39.000000', NULL, 1),
(6665690, 996117, 114225, '<td valign="top">Such brilliant color. It''s really nice to see the smoothness of the flower play agains the hairy/roughness of the bees.</td>', 'Such brilliant color. It''s really nice to see the smoothness of the flower play agains the hairy/roughness of the bees.', '2012-02-06 22:02:50.000000', NULL, 1),
(6665691, 994074, 114225, '<td valign="top">The vintage feel to the processing actually works pretty well.</td>', 'The vintage feel to the processing actually works pretty well.', '2012-02-06 22:03:45.000000', NULL, 1),
(6665692, 996088, 114225, '<td valign="top">What a fun way to remember the day.</td>', 'What a fun way to remember the day.', '2012-02-06 22:04:20.000000', NULL, 1),
(6665693, 996183, 49018, '<td valign="top">Paulbw, perhaps?<br/>Excellent play of shapes and duotone.<br/>9</td>', 'Paulbw, perhaps?Excellent play of shapes and duotone.9', '2012-02-06 22:04:24.000000', NULL, 1),
(6665696, 991720, 114225, '<td valign="top">This photo has a very serene feel to it.</td>', 'This photo has a very serene feel to it.', '2012-02-06 22:04:54.000000', NULL, 1),
(6665697, 996126, 114225, '<td valign="top">Great bit of minimalism.</td>', 'Great bit of minimalism.', '2012-02-06 22:05:11.000000', NULL, 1),
