(6665704, 996529, 114225, '<td valign="top">Great title for this powerful image.</td>', 'Great title for this powerful image.', '2012-02-06 22:08:22.000000', NULL, 1),
(6665708, 993867, 49018, '<td valign="top">truly excellent postprocessing, I love how the light is encapsulated in darkness. And the only escape point for the eye, the bottom reflection, can only suggest to go back to the grass and the trees.<br/>Quite in love with this.<br/>10</td>', 'truly excellent postprocessing, I love how the light is encapsulated in darkness. And the only escape point for the eye, the bottom reflection, can only suggest to go back to the grass and the trees.Quite in love with this.10', '2012-02-06 22:15:49.000000', NULL, 1),
(6665712, 996441, 49018, '<td valign="top">Straight from SF, I like it a lot.</td>', 'Straight from SF, I like it a lot.', '2012-02-06 22:17:07.000000', NULL, 1),
(6665714, 992247, 49018, '<td valign="top">I like it. My only nitpick would be that the non gradual DOF is a bit disconcerting, which makes the boy stand on the scene without blending with it. Which might be the intention, of course.</td>', 'I like it. My only nitpick would be that the non gradual DOF is a bit disconcerting, which makes the boy stand on the scene without blending with it. Which might be the intention, of course.', '2012-02-06 22:19:42.000000', NULL, 1),
(6665717, 996540, 49018, '<td valign="top">Excellent black and white treatment and choice of optics.</td>', 'Excellent black and white treatment and choice of optics.', '2012-02-06 22:22:53.000000', NULL, 1),
(6665720, 996126, 66515, '<td valign="top">I love the simplicity and almost graphic feel to this image.</td>', 'I love the simplicity and almost graphic feel to this image.', '2012-02-06 22:24:51.000000', NULL, 1),
(6665721, 996515, 49018, '<td valign="top">Pray for us, that from the straw we are never separated.<br/>Indeed, a very unusual expression :)<br/>Very effective B&amp;W.</td>', 'Pray for us, that from the straw we are never separated.Indeed, a very unusual expression :)Very effective B&W.', '2012-02-06 22:24:53.000000', NULL, 1),
(6665723, 996427, 49018, '<td valign="top">Excellent BW.</td>', 'Excellent BW.', '2012-02-06 22:26:29.000000', NULL, 1),
(6665724, 995632, 66515, '<td valign="top">I''d prefer the colors to be softer and more natural.</td>', 'I''d prefer the colors to be softer and more natural.', '2012-02-06 22:26:29.000000', NULL, 1),
(6665726, 991868, 66515, '<td valign="top">You''ve balanced the ambient and the flash but the flash is on camera. Try to follow the direction that the natural light is coming from and add to it rather than trying to fight against it. The results will look more natural.</td>', 'You''ve balanced the ambient and the flash but the flash is on camera. Try to follow the direction that the natural light is coming from and add to it rather than trying to fight against it. The results will look more natural.', '2012-02-06 22:29:17.000000', NULL, 1),
(6665729, 996426, 49018, '<td valign="top">And not a key in sight.<br/>I like this but, unless I am missing something, I find the vignetting on top a bit constraining, which now that I think about it would go well with the concept.<br/>8</td>', 'And not a key in sight.I like this but, unless I am missing something, I find the vignetting on top a bit constraining, which now that I think about it would go well with the concept.8', '2012-02-06 22:32:19.000000', NULL, 1),
